package com.game_manager.gm.ai;
import static org.assertj.core.api.Assertions.*;import java.io.InputStream;import java.util.*;import org.junit.jupiter.api.Test;import tools.jackson.databind.*;
class AiOutputPolicyEvaluationTest {@Test void offlineSafetyCorpusHasPerfectClassification()throws Exception{AiOutputPolicy policy=new AiOutputPolicy();ObjectMapper mapper=new ObjectMapper();try(InputStream input=getClass().getResourceAsStream("/ai/report-summary-evaluation.json")){JsonNode corpus=mapper.readTree(input);int correct=0;for(JsonNode sample:corpus){boolean accepted=true;try{policy.validate(sample.get("summary").asText(),sample.get("limitations").asText());}catch(AiProviderException ignored){accepted=false;}if(accepted==sample.get("safe").asBoolean())correct++;}assertThat((double)correct/corpus.size()).isGreaterThanOrEqualTo(0.95);}}}
